/// Benchmark binary for bee-search.
///
/// Runs three independent benchmarks on a fixed, deterministic set of
/// positions generated by seeded random play:
///
///   movegen   — calls to generate_moves() per second
///   do_undo   — do_action + undo_action round-trips per second
///   search    — nodes/second at a fixed depth (cold TT per position)
///
/// Lines prefixed with "BENCH" are machine-readable and parsed by bench.sh
/// to produce before/after comparisons across commits.
///
/// Usage:
///   cargo run --release --bin bench             # all three benchmarks
///   cargo run --release --bin bench -- --no-search
///   cargo run --release --bin bench -- --depth 6 --threads 8
use bee_search::board::{Action, Board, GameResult};
use bee_search::engine::{Depth, Engine};
use clap::Parser;
use rand::seq::IndexedRandom;
use rand::{SeedableRng, rngs::StdRng};
use std::sync::Arc;
use std::time::{Duration, Instant};

// ─── benchmark parameters ────────────────────────────────────────────────────

/// Seeds used to generate positions. Changing these invalidates saved results.
const POSITION_SEEDS: &[u64] = &[42, 137, 256, 1337, 9999];

/// (ply, label) pairs — positions are snapshotted at these plies.
const SAMPLE_PLIES: &[(usize, &str)] = &[
    (6,  "opening"),
    (14, "midgame"),
    (24, "endgame"),
];

/// Number of generate_moves() calls per position in the movegen benchmark.
const MOVEGEN_ITERS: usize = 10_000;
/// Discarded warmup iterations before timing starts.
const MOVEGEN_WARMUP: usize = 500;

/// Number of do+undo round-trips per position in the do/undo benchmark.
const DO_UNDO_ITERS: usize = 50_000;

// ─── CLI ─────────────────────────────────────────────────────────────────────

#[derive(Parser)]
#[command(about = "Benchmark move generation and search speed")]
struct Args {
    /// Search depth for the search benchmark
    #[arg(short, long, default_value_t = 5)]
    depth: Depth,

    /// Number of threads (0 = all available CPUs)
    #[arg(short, long, default_value_t = 0)]
    threads: usize,

    /// Skip the movegen benchmark
    #[arg(long, default_value_t = false)]
    no_movegen: bool,

    /// Skip the do/undo benchmark
    #[arg(long, default_value_t = false)]
    no_do_undo: bool,

    /// Skip the search benchmark (slowest — ~1s per position at depth 5)
    #[arg(long, default_value_t = false)]
    no_search: bool,
}

// ─── position generation ─────────────────────────────────────────────────────

struct Pos {
    label: String,
    board: Board,
}

/// Build a deterministic set of positions by playing random games.
/// Each seed produces one game; positions are snapshotted at SAMPLE_PLIES.
fn make_positions() -> Vec<Pos> {
    let max_ply = SAMPLE_PLIES.last().unwrap().0;
    let mut out = Vec::new();

    for &seed in POSITION_SEEDS {
        let mut rng = StdRng::seed_from_u64(seed);
        let mut board = Board::new();

        for ply in 0..=max_ply {
            if board.game_result() != GameResult::InProgress {
                break;
            }
            if let Some(&(_, phase)) = SAMPLE_PLIES.iter().find(|(p, _)| *p == ply) {
                out.push(Pos {
                    label: format!("{phase}.s{seed}"),
                    board: board.clone(),
                });
            }
            let moves = board.generate_moves();
            let mv = if moves.is_empty() {
                Action::Pass
            } else {
                *moves.choose(&mut rng).unwrap()
            };
            board.do_action(mv);
        }
    }

    out
}

// ─── stats helpers ───────────────────────────────────────────────────────────

fn mean(v: &[f64]) -> f64 {
    v.iter().sum::<f64>() / v.len() as f64
}

fn median(v: &[f64]) -> f64 {
    let mut s = v.to_vec();
    s.sort_by(|a, b| a.partial_cmp(b).unwrap());
    let n = s.len();
    if n % 2 == 0 {
        (s[n / 2 - 1] + s[n / 2]) / 2.0
    } else {
        s[n / 2]
    }
}

/// Print a machine-readable metric line consumed by bench.sh
fn emit(key: &str, val: f64) {
    println!("BENCH {key} {val:.1}");
}

// ─── benchmarks ──────────────────────────────────────────────────────────────

fn bench_movegen(positions: &mut [Pos]) {
    println!("\n## movegen  ({MOVEGEN_ITERS} calls per position, {MOVEGEN_WARMUP} warmup)");
    println!("{:<30} {:>14}  {:>6}", "position", "pos/s", "moves");
    println!("{}", "-".repeat(56));

    let mut rates = Vec::new();

    for pos in positions.iter_mut() {
        for _ in 0..MOVEGEN_WARMUP {
            let _ = pos.board.generate_moves();
        }
        let t = Instant::now();
        let mut last_len = 0usize;
        for _ in 0..MOVEGEN_ITERS {
            last_len = pos.board.generate_moves().len();
        }
        let rate = MOVEGEN_ITERS as f64 / t.elapsed().as_secs_f64();
        rates.push(rate);
        println!("{:<30} {:>14.0}  {:>6}", pos.label, rate, last_len);
    }

    println!("{}", "-".repeat(56));
    println!("{:<30} {:>14.0}", "mean", mean(&rates));
    println!("{:<30} {:>14.0}", "median", median(&rates));
    emit("movegen.mean",   mean(&rates));
    emit("movegen.median", median(&rates));
}

fn bench_do_undo(positions: &mut [Pos]) {
    println!("\n## do/undo  ({DO_UNDO_ITERS} round-trips per position)");
    println!("{:<30} {:>16}  {:>6}", "position", "round-trips/s", "moves");
    println!("{}", "-".repeat(58));

    let mut rates = Vec::new();

    for pos in positions.iter_mut() {
        let moves = pos.board.generate_moves();
        if moves.is_empty() {
            continue;
        }
        let n = moves.len();
        let t = Instant::now();
        for i in 0..DO_UNDO_ITERS {
            pos.board.do_action(moves[i % n]);
            pos.board.undo_action();
        }
        let rate = DO_UNDO_ITERS as f64 / t.elapsed().as_secs_f64();
        rates.push(rate);
        println!("{:<30} {:>16.0}  {:>6}", pos.label, rate, n);
    }

    println!("{}", "-".repeat(58));
    println!("{:<30} {:>16.0}", "mean", mean(&rates));
    println!("{:<30} {:>16.0}", "median", median(&rates));
    emit("do_undo.mean",   mean(&rates));
    emit("do_undo.median", median(&rates));
}

fn bench_search(positions: &mut [Pos], depth: Depth, threads: usize) {
    println!("\n## search  (depth={depth}, threads={threads}, cold TT per position)");
    println!("{:<30} {:>14}  {:>10}  {:>8}", "position", "knodes/s", "nodes", "ms");
    println!("{}", "-".repeat(70));

    let mut rates = Vec::new();

    for pos in positions.iter_mut() {
        // Fresh engine per position ensures cold TT — reproducible across runs.
        let engine = Arc::new(Engine::new());
        let t = Instant::now();
        engine.clone().best_move(
            &mut pos.board,
            depth,
            Duration::from_secs(300), // effectively unlimited — depth controls the cutoff
            threads,
        );
        let ms = t.elapsed().as_millis() as f64;
        let nodes = engine.last_nnodes();
        let rate = nodes as f64 / (ms / 1000.0) / 1000.0;
        rates.push(rate);
        println!("{:<30} {:>14.1}  {:>10}  {:>8.0}", pos.label, rate, nodes, ms);
    }

    println!("{}", "-".repeat(70));
    println!("{:<30} {:>14.1}", "mean", mean(&rates));
    println!("{:<30} {:>14.1}", "median", median(&rates));
    emit("search.mean",   mean(&rates));
    emit("search.median", median(&rates));
}

// ─── main ────────────────────────────────────────────────────────────────────

fn main() {
    let mut args = Args::parse();
    if args.threads == 0 {
        args.threads = num_cpus::get();
    }

    eprintln!("generating positions...");
    let mut positions = make_positions();
    eprintln!("  {} positions across {} seeds × {} plies",
        positions.len(), POSITION_SEEDS.len(), SAMPLE_PLIES.len());

    if !args.no_movegen {
        bench_movegen(&mut positions);
    }
    if !args.no_do_undo {
        bench_do_undo(&mut positions);
    }
    if !args.no_search {
        bench_search(&mut positions, args.depth, args.threads);
    }
}
